def file_hash(path):
    result = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(2 ** 20), b''):
            result.update(block)
    return result.hexdigest()

def dependency_report():
    modules = {'numpy': 'numpy', 'pandas': 'pandas', 'pyarrow': 'pyarrow', 'PIL': 'Pillow', 'sklearn': 'scikit-learn', 'torch': 'torch', 'matplotlib': 'matplotlib', 'psutil': 'psutil', 'tldextract': 'tldextract', 'pyspark': 'pyspark'}
    versions = {}
    for module, package in modules.items():
        try:
            versions[package] = package_metadata.version(package)
        except package_metadata.PackageNotFoundError:
            versions[package] = None
    missing = [k for k, v in versions.items() if v is None and k != 'pyspark']
    memory = psutil.virtual_memory()
    return dict(core_status='PASS' if not missing else 'FAIL', missing_core=missing, versions=versions, spark_status='AVAILABLE' if versions['pyspark'] and shutil.which('java') else 'NOT_AVAILABLE', java=shutil.which('java'), python=platform.python_version(), platform=platform.platform(), cuda=torch.cuda.is_available(), available_ram_gb=memory.available / 1000000000.0, free_disk_gb=shutil.disk_usage(ROOT).free / 1000000000.0)

def preflight(settings):
    settings.checked()
    report = dependency_report()
    reasons = list(report['missing_core'])
    warnings = []
    csv = RAW_DIRECTORY / 'phishark2026_public_metadata.csv'
    if not csv.is_file():
        reasons.append('Original metadata CSV missing from data/raw')
    if settings.mode == 'FULL_EXPERIMENT' and csv.is_file():
        expected = pd.read_csv(csv, usecols=['archive_filename'])['archive_filename'].astype(str)
        present = {p.name for p in RAW_DIRECTORY.glob('*.zip')}
        missing = sorted(set(expected) - present)
        report['expected_archives'] = int(len(expected))
        report['available_archives'] = int(len(set(expected) & present))
        report['missing_archive_count'] = len(missing)
        report['missing_archive_examples'] = missing[:5]
        # A handful of absent/corrupt archives can be quarantined, but never silently
        # train on a CSV while most ZIPs are absent.
        allowed_missing = max(5, int(len(expected) * 0.001))
        if len(missing) > allowed_missing:
            reasons.append(f'FULL requires raw ZIP corpus: {len(missing)} archives missing (> {allowed_missing} allowed)')
        elif missing:
            warnings.append(f'{len(missing)} absent ZIPs will be quarantined with provenance')
    if settings.mode == 'FULL_EXPERIMENT':
        if report['available_ram_gb'] < 3:
            warnings.append('RAM disponible inferieure a 3 Go : execution autorisee a la demande de l utilisateur ; risque de ralentissement ou de manque de memoire.')
        # Already allocated image caches need not be budgeted a second time.
        config = {k: v for k, v in asdict(settings).items() if k not in ('protocol', 'epochs', 'patience', 'bootstrap_replicates')}
        cached = False
        for complete in (ROOT / 'data/processed').glob('*/complete.json'):
            try:
                info = load_json(complete)
                cached = (info['binding']['code'] == source_signature()
                          and digest(info['binding']['config']) == digest(config)
                          and (complete.parent / 'canonical.parquet').is_file())
            except (OSError, ValueError, KeyError):
                cached = False
            if cached:
                break
        required_disk = 2 if cached else 6
        report['disk_budget_scope'] = 'remaining artifacts; cache integrity checked by extract' if cached else 'fresh extraction and artifacts'
        report['required_free_disk_gb'] = required_disk
        if report['free_disk_gb'] < required_disk:
            reasons.append(f'FULL requires at least {required_disk} GB free disk ({report["disk_budget_scope"]})')
        if report['spark_status'] != 'AVAILABLE':
            reasons.append('FULL requires PySpark and Java')
    report.update(status='BLOCKED' if reasons else 'PASS', reasons=reasons, warnings=warnings)
    return report

FEATURE_VERSION = 'raw-json-v1'
DEFINITIONS = (('dns', 'records', 'count'), ('whois', 'creation_date', 'present'), ('whois', 'expiration_date', 'present'), ('whois', 'registrar', 'present'), ('whois', 'name_servers', 'count'), ('ip_geo', 'ip', 'present'), ('ip_geo', 'country_code', 'present'), ('ports', 'open_ports', 'count'), ('tls_certificate', 'success', 'boolean'), ('tls_certificate', 'issuer', 'present'), ('tls_certificate', 'subject', 'present'), ('tls_certificate', 'subject_alternative_names', 'count'), ('web_page', 'title', 'length'), ('web_page', 'description', 'length'), ('web_page', 'detected_technologies', 'count'), ('web_page', 'outgoing_links', 'count'), ('web_page', 'total_url_count', 'number'), ('redirection', 'redirect_count', 'number'), ('redirection', 'chain', 'count'), ('compliance_files', 'checked_files', 'count'), ('compliance_files', 'found_files', 'count'))
FEATURES = tuple(('_'.join(item) for item in DEFINITIONS))


def url_model_text(value):
    """Same transformation for vocab, training, audit and inference; never fetch URL."""
    raw = '' if value is None else str(value).strip()
    if not raw:
        return ''
    try:
        parsed = urlsplit(raw if '://' in raw or raw.startswith('//') else '//'+raw)
        if parsed.netloc:
            return (parsed.netloc + (parsed.path or '/') + ('?' + parsed.query if parsed.query else '')).lower()
    except ValueError:
        pass
    # Malformed input remains observable, but the scheme and fragment are excluded.
    return re.sub(r'^[a-z][a-z0-9+.-]*://', '', raw, flags=re.I).split('#', 1)[0].lower()

def finite_nonnegative(value):
    try:
        number = float(value)
        return number if np.isfinite(number) and number >= 0 else np.nan
    except (TypeError, ValueError):
        return np.nan

def normalized_status(value):
    number = finite_nonnegative(value)
    return int(number) if np.isfinite(number) and number.is_integer() and (100 <= number <= 599) else None

def extract_numeric(data):
    out = []
    for filename, field, operation in DEFINITIONS:
        value = data.get('data/' + filename + '.json', {}).get(field)
        result = np.nan
        if value is not None:
            if operation == 'present':
                result = float(bool(value))
            elif operation == 'boolean' and str(value).lower() in ('true', 'false', '0', '1'):
                result = float(str(value).lower() in ('true', '1'))
            elif operation == 'count':
                if isinstance(value, (list, dict)):
                    result = float(len(value))
                elif isinstance(value, str) and field == 'name_servers':
                    result = float(len(value.split()))
            elif operation == 'length' and isinstance(value, str):
                result = float(len(value))
            elif operation == 'number':
                result = finite_nonnegative(value)
        out.append(result)
    return np.array(out, np.float32)

def assert_features(columns):
    if tuple(columns) != FEATURES:
