def spark_schema():
    from pyspark.sql.types import StructType, StructField, StringType, IntegerType, FloatType
    return StructType([StructField('scan_id', StringType(), False), StructField('label_id', IntegerType(), False), StructField('split', StringType(), False)] + [StructField(name, FloatType(), True) for name in FEATURES])

def canonical_benchmark_table(frame):
    data = frame[['scan_id', 'label_id', 'split', *FEATURES]].copy()
    data['scan_id'] = data.scan_id.astype('string')
    data['split'] = data.split.astype('string')
    data['label_id'] = data.label_id.astype('int32')
    for name in FEATURES:
        data[name] = data[name].astype('float32')
    return data.sort_values('scan_id').reset_index(drop=True)

def validate_benchmark_table(frame, n, positives):
    if len(frame) != n or not frame.scan_id.is_unique or int(frame.label_id.sum()) != positives:
        raise ValueError('Benchmark validation failure')

def write_pandas_dataset(frame, target, partitioned):
    target = Path(target)
    if target.exists():
        raise FileExistsError('Never overwrite a benchmark attempt')
    target.mkdir(parents=True)
    if partitioned:
        for role, part in frame.groupby('split', observed=True):
            if role not in ('train_encoder', 'train_fusion', 'validation', 'calibration', 'test'):
                raise ValueError('Unsafe partition value')
            directory = target / f'split={role}'
            directory.mkdir()
            part.drop(columns='split').to_parquet(directory / 'p.parquet', index=False, compression='snappy')
    else:
        frame.to_parquet(target / 'p.parquet', index=False, compression='snappy')

class BenchmarkMemory:
    """Sample summed process/JVM RSS; shared pages can be counted twice."""

    def __init__(self):
        self.stop = threading.Event()
        self.peak = 0
        self.thread = None

    def sample(self):
        while not self.stop.is_set():
            process = psutil.Process()
            total = process.memory_info().rss
            for child in process.children(recursive=True):
                try:
                    total += child.memory_info().rss
                except psutil.Error:
                    pass
            self.peak = max(self.peak, total)
            self.stop.wait(0.05)

    def __enter__(self):
        self.thread = threading.Thread(target=self.sample, daemon=True)
        self.thread.start()
        return self

    def __exit__(self, *args):
        self.stop.set()
        self.thread.join(timeout=2)

def benchmark(context):
    report = dependency_report()
    s = context['settings']
    directory = context['run'] / 'bd2'
    directory.mkdir(exist_ok=True)
    records = []
    spark = None
    startup = None
    if report['spark_status'] == 'AVAILABLE' and report['available_ram_gb'] >= 2:
        from pyspark.sql import SparkSession
        try:
            start = time.perf_counter()
            spark = SparkSession.builder.master(f'local[{s.threads}]').appName('PhiSharkFairBenchmark').config('spark.ui.enabled', 'false').getOrCreate()
            startup = time.perf_counter() - start
        except Exception as error:
            records.append(dict(engine='spark_local', status='FAIL', reason=type(error).__name__ + ':' + str(error)[:180]))
    else:
        records.append(dict(engine='spark_local', status='NOT_AVAILABLE' if report['spark_status'] != 'AVAILABLE' else 'BLOCKED', reason='PySpark/Java absent or less than 2 GB available RAM'))
    frame = canonical_benchmark_table(context['frame'])
    try:
        for fraction in s.benchmark_fractions:
            subset = frame.iloc[:max(1, int(len(frame) * fraction))]
            for repetition in range(s.benchmark_repeats):
                for scenario in ('A_unpartitioned', 'B_partitioned'):
                    records.append(measure_parquet_case(context, subset, scenario, 'pandas_pyarrow', repetition, fraction))
                    if spark is not None:
                        records.append(measure_parquet_case(context, subset, scenario, 'spark_local', repetition, fraction, spark))
    finally:
        if spark is not None:
            spark.stop()
    result = pd.DataFrame(records)
    result.to_csv(directory / 'measurements.csv', index=False)
    save_json(directory / 'scope.json', dict(extraction_seconds=context['provenance']['extraction']['seconds'], spark_startup_seconds=startup, spark_startup_included=False, cold_cache='NOT_CONTROLLED', multinode=False, resources=report, scenarios=dict(A_unpartitioned='one Parquet data file for both engines', B_partitioned='Hive split=role for both engines'), integrity='identical readback and exact canonical frame equality included in time'))
    return result
